      "welcome": {
        "title": "👋 Chào mừng đến với Sub2API",
        "description": "<div style=\"line-height: 1.8;\"><p style=\"margin-bottom: 16px;\">Sub2API là nền tảng cổng dịch vụ AI mạnh mẽ giúp bạn dễ dàng quản lý và phân phối các dịch vụ AI.</p><p style=\"margin-bottom: 12px;\"><b>🎯 Các tính năng cốt lõi:</b></p><ul style=\"margin-left: 20px; margin-bottom: 16px;\"><li>📦 <b>Nhóm Quản lý</b> - Tạo các cấp dịch vụ (VIP, Dùng thử miễn phí, v.v.)</li><li>🔗 <b>Nhóm tài khoản</b> - Kết nối nhiều tài khoản dịch vụ AI ngược dòng</li><li>🔑 <b>Phân phối khóa</b> - Tạo Khóa API độc lập cho người dùng</li><li>💰 <b>Kiểm soát thanh toán</b> - Quản lý hạn ngạch và tỷ lệ linh hoạt</li></ul><p style=\"color: #10b981; font-weight: 600;\">Hãy hoàn tất thiết lập ban đầu sau 3 phút →</p></div>",
        "nextBtn": "Bắt đầu thiết lập 🚀",
        "prevBtn": "Bỏ qua"
      },
